// 1. Verify successful authentication status code
pm.test("HTTP Status is 200 OK", function () {
    pm.response.to.have.status(200);
});

// 2. Strict response performance benchmark (< 250ms SLA)
pm.test("Performance Benchmark: Response time is under 250ms SLA", function () {
    pm.expect(pm.response.responseTime).to.be.below(250);
});

// 3. Extract and chain token to environment variables pool
const responseData = pm.response.json();
pm.test("Token Extraction: Secure JWT generated cleanly", function () {
    pm.expect(responseData).to.have.property("accessToken");

    // Inject token directly into active environment variables pool
    pm.environment.set("jwtToken", responseData.accessToken);
});

pm.test("HTTP Status Code is 201 Created", function () {
    pm.response.to.have.status(201);
});

// Using a unique variable name to completely prevent re-declaration errors
const accountResponsePayload = pm.response.json();

if (accountResponsePayload.accountId) {
    pm.environment.set("accountId", accountResponsePayload.accountId);
}

const jsonSchemaBlueprint = {
    "type": "object",
    "required": ["accountId", "status", "balance", "type"],
    "properties": {
        "accountId": {"type": "string", "pattern": "^ACC-[0-9]+$"},
        "status": {"type": "string", "enum": ["ACTIVE", "PENDING"]},
        "balance": {"type": "number"},
        "type": {"type": "string"}
    }
};

pm.test("Response body matches strict corporate JSON Schema structural layout", function () {
    pm.response.to.have.jsonSchema(jsonSchemaBlueprint);
});

// 1. Security Check: Assert the server rejected the unauthenticated entry
pm.test("Security Check: HTTP Status Code is 403 Forbidden", function () {
    pm.response.to.have.status(403);
});

// 2. Structural Error Response String Validation
pm.test("Error payload contains clear security violation messaging", function () {
    const responseData = pm.response.json();
    pm.expect(responseData.detail).to.include("Access Denied");
});

// 1. Assert Response Status Code Compliance
pm.test("HTTP Status is 200 OK", function () {
    pm.response.to.have.status(200);
});

// 2. Data Ledger Validation: Cross-verify account IDs and balance structures
pm.test("Data Ledger Check: Returned account matches requested ID", function () {
    const responseData = pm.response.json();
    const expectedId = pm.environment.get("accountId");

    // Cross-verify that the banking ledger matches our environment state
    pm.expect(responseData.accountId).to.eql(expectedId);
    pm.expect(responseData.status).to.eql("ACTIVE");
    pm.expect(responseData.balance).to.be.a("number");
});
